window.NWSDemoDB = (function(){
  var KEY = 'nws2027demo_db2';
  function save(d){ try { localStorage.setItem(KEY, JSON.stringify(d)); } catch(e){} }
  function get(){
    try { var d = JSON.parse(localStorage.getItem(KEY)); if (d) return d; } catch(e){}
    var s = JSON.parse(JSON.stringify(window.NWS_DEMO_SEED)); save(s); return s;
  }
  function reset(){ try { localStorage.removeItem(KEY); Object.keys(localStorage).filter(function(k){ return k.indexOf('nwsg.') === 0; }).forEach(function(k){ localStorage.removeItem(k); }); sessionStorage.removeItem('nws2027demo_pin'); } catch(e){} }
  return {get: get, save: save, reset: reset};
})();
